    listServices: {
        parameters: {
            query: {
                /** @description Inclusive window start, Unix ns. */
                from: components["parameters"]["From"];
                /** @description Exclusive window end, Unix ns. Window ≤ 7 days. */
                to: components["parameters"]["To"];
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Services observed in the window with SERVER-span statistics. */
            200: {
                headers: {
                    "Cache-Control": components["headers"]["NoStore"];
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        window: components["schemas"]["Window"];
                        freshness: components["schemas"]["Freshness"];
                        /** @description Every service with any span in the window, sorted by name. Services with no SERVER spans have server.population.sample_count = 0. */
                        services: components["schemas"]["ServiceSummary"][];
                    };
                };
            };
            400: components["responses"]["BadRequest"];
            401: components["responses"]["Unauthorized"];
            503: components["responses"]["Unavailable"];
        };
    };
