    getServerLatency: {
        parameters: {
            query: {
                /** @description Inclusive window start, Unix ns. */
                from: components["parameters"]["From"];
                /** @description Exclusive window end, Unix ns. Window ≤ 7 days. */
                to: components["parameters"]["To"];
                service?: components["parameters"]["ServiceFilter"];
                operation?: string;
                bucket_seconds?: 60 | 300 | 900 | 3600;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /**
             * @description Dense time series of observed SERVER span latency, throughput and errors. Every bucket in
             *     the window is present; empty buckets have `stats: null`. Window/bucket combinations
             *     producing more than 2,000 points are rejected (400 window_too_large).
             */
            200: {
                headers: {
                    "Cache-Control": components["headers"]["NoStore"];
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["LatencySeries"];
                };
            };
            400: components["responses"]["BadRequest"];
            401: components["responses"]["Unauthorized"];
            503: components["responses"]["Unavailable"];
        };
    };
